  test "decimal arithmetic and rounding match java.math.BigDecimal" do
    header = "(ns decimal.oracle (:require [decimal :as d]))"
    BeamLisp.Compiler.eval_string(header)
    env = BeamLisp.Compiler.new_env("decimal.oracle")

    failures =
      for {jvm, bl, expected} <- @rows,
          got = run(bl, env),
          got != expected,
          do: "#{jvm}\n    JVM: #{inspect(expected)}\n    bl:  #{inspect(got)} (#{bl})"

    assert failures == [], "#{length(failures)} of #{length(@rows)} rows diverge:\n\n" <> Enum.join(failures, "\n\n")
  end

  defp run(src, env) do
    v = BeamLisp.Compiler.eval_string(src, env)
    BeamLisp.RT.print_str(v) |> String.trim("\"")
  rescue
    _ -> "ERROR"
  catch
    _, _ -> "ERROR"
  end
